// Normalise a competition name for tolerant matching between the platform's
// league names and JADE's. Platform and JADE names drift in three ways:
//   - season position: "Geelong FNL 2026" vs "2026 Champions IGA Seniors"
//   - wording: "Goulburn Valley FNL" vs JADE's "Goulburn Valley League"
//   - casing/spacing
// So we strip any 4-digit year (anywhere), alias FNL/FL → League, lowercase,
// and collapse whitespace. Matching is done on this normalised form.
function normaliseCompName(name: string): string {
  return name
    .trim()
    .toLowerCase()
    .replace(/\b(19|20)\d{2}\b/g, "") // drop a season year anywhere
    .replace(/\bfnl\b/g, "league") // Football Netball League
    .replace(/\bfl\b/g, "league") // Football League
    .replace(/\s+/g, " ")
    .trim();
}

// normalised name -> comp id. Built ascending by season so the most recent
// season wins when several seasons share a normalised name.
const BY_NORM = new Map<string, number>(
  [...JADE_COMPS]
    .sort((a, b) => (a.season < b.season ? -1 : 1))
    .map((c) => [normaliseCompName(c.name), c.compId] as const)
);

/**
 * Resolve a JADE competition id from a competition/league name. Matches on a
 * normalised form (year-stripped, FNL/FL→League, lowercased): exact first,
 * then a prefix match in either direction. Returns null when nothing matches.
 */
export function compIdForName(name: string): number | null {
  const q = normaliseCompName(name);
  if (!q) return null;
  const exact = BY_NORM.get(q);
  if (exact != null) return exact;
  for (const [key, id] of BY_NORM) {
    if (key.startsWith(q) || q.startsWith(key)) return id;
  }
  return null;
}

